import type { TopUpIntentStatusView } from '@skillswap/contracts';
import type { TopUpIntentRepository } from './port/out/top-up-intent-repository';
import type { GetTopUpIntentPort } from './port/in/get-top-up-intent';

/** Any RFC 4122 shape; `top_up_intents.id` is generated by `gen_random_uuid()`. */
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * FR-008 / ADR-033: raised when the intent does not exist **or** belongs to
 * someone else. One error for both cases on purpose — a distinct 403 would tell
 * a probing caller that the id is real.
 */
export class TopUpIntentNotFoundError extends Error {
  constructor() {
    super('Top-up intent not found');
    this.name = 'TopUpIntentNotFoundError';
  }
}

/** FR-008 / ADR-033: owner-scoped read of one top-up intent, for client polling. */
export class GetTopUpIntentUseCase implements GetTopUpIntentPort {
  constructor(private readonly intents: TopUpIntentRepository) {}

  async execute(ownerId: string, intentId: string): Promise<TopUpIntentStatusView> {
    // `top_up_intents.id` is a uuid column, so a non-uuid path segment would make
    // Postgres raise `22P02` and surface as a 500. Reject it as "not found"
    // instead: an id that cannot exist and an id that does not exist are the
    // same answer to the caller.
    if (!UUID_PATTERN.test(intentId)) {
      throw new TopUpIntentNotFoundError();
    }

    const intent = await this.intents.findById(intentId);
    if (intent === null || intent.ownerId !== ownerId) {
      throw new TopUpIntentNotFoundError();
    }
    return {
      id: intent.id,
      ownerId: intent.ownerId,
      provider: intent.provider,
      providerRef: intent.providerRef,
      amountVnd: intent.amountVnd,
      amountCredits: intent.amountCredits,
      status: intent.status,
      paidAmountVnd: intent.paidAmountVnd,
      paidAt: intent.paidAt === null ? null : intent.paidAt.toISOString(),
    };
  }
}
